alcance_autorizado = {"203.0.113.10", "203.0.113.11"}

hallazgos = [
    {"objetivo": "203.0.113.10", "puerto": 443, "vulnerabilidad": "TLS 1.0 habilitado", "severidad": "media"},
    {"objetivo": "203.0.113.10", "puerto": 22, "vulnerabilidad": "SSH acepta contrasenas debiles", "severidad": "alta"},
    {"objetivo": "198.51.100.5", "puerto": 3389, "vulnerabilidad": "RDP expuesto a Internet", "severidad": "critica"},
]

def dentro_de_alcance(objetivo):
    return objetivo in alcance_autorizado

for h in hallazgos:
    if not dentro_de_alcance(h["objetivo"]):
        print(f"DESCARTADO (fuera de alcance, requiere autorizacion): {h['objetivo']}:{h['puerto']}")
        continue
    print(f"{h['objetivo']}:{h['puerto']} - {h['vulnerabilidad']} [{h['severidad']}]")

orden_severidad = {"critica": 3, "alta": 2, "media": 1, "baja": 0}
validos = [h for h in hallazgos if dentro_de_alcance(h["objetivo"])]
validos.sort(key=lambda h: orden_severidad[h["severidad"]], reverse=True)
print("Prioridad de remediacion:", [h["vulnerabilidad"] for h in validos])
